import { useState } from "react";
import usFlag from "./flags/eng.png";
import auFlag from "./flags/au.png";

const LanguageSelector = ({ language, onChange }) => {
  const [open, setOpen] = useState(false);

  const options = [
    { value: "en-US", label: "English (US)", flag: usFlag },
    { value: "en-GB", label: "Kirol (AU)", flag: auFlag },
  ];

  const selected = options.find((opt) => opt.value === language);

  return (
    <div className="custom-select">
      <button onClick={() => setOpen(!open)} className="custom-select-btn">
        <img src={selected.flag} alt="" className="flag-icon" />
        {selected.label}
      </button>

      {open && (
        <ul className="custom-select-list">
          {options.map((opt) => (
            <li
              key={opt.value}
              onClick={() => {
                onChange(opt.value);
                setOpen(false);
              }}
            >
              <img src={opt.flag} alt="" className="flag-icon" />
              {opt.label}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default LanguageSelector;
